namespace Challenge;public record Query(string Sql,IReadOnlyDictionary<string,object> Parameters);public static class SearchQuery{public static Query Build(string filter,string sort,string direction){var column=sort switch{"name"=>"name","createdAt"=>"created_at",_=>throw new ArgumentException("Unsupported sort")};var dir=direction.ToLowerInvariant() switch{"asc"=>"ASC","desc"=>"DESC",_=>throw new ArgumentException("Unsupported direction")};return new($"SELECT id,name FROM products WHERE name ILIKE @filter ORDER BY {column} {dir}",new Dictionary<string,object>{{"filter",$"%{filter}%"}});}}
